static void page_products(FILE *out, const Model *m) {
    layout_begin(out, "Products");              /* <head> + chrome */
    for (size_t i = 0; i < m->n_products; i++)
        frag_product_row(out, &m->products[i]); /* repeated subview */
    frag_footer(out, m->year);
    layout_end(out);
}
